import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt

# Load the feature-engineered dataset generated by model_building.py
df = pd.read_csv('feature_engineered_dataset.csv')

# Set visual style
sns.set_theme(style="whitegrid")

# 1. Analyze Revenue by Campaign Type
plt.figure(figsize=(10, 6))
sns.barplot(data=df, x='Campaign_Type', y='Revenue', estimator=sum, errorbar=None)
plt.title('Total Revenue by Campaign Type')
plt.xticks(rotation=45)
plt.show()

# 2. Relationship between Spend (Acquisition_Cost) and Revenue
plt.figure(figsize=(8, 6))
sns.scatterplot(data=df, x='Acquisition_Cost', y='Revenue', hue='Profit_Flag', palette='viridis')
plt.title('Acquisition Cost vs. Revenue (Segmented by Profitability)')
plt.show()

# 3. Analyze Customer Segments and ROI
plt.figure(figsize=(10, 6))
sns.boxplot(data=df, x='Customer_Segment', y='ROI')
plt.title('ROI Distribution Across Customer Segments')
plt.show()

# 4. Correlation Heatmap for Numerical Features
plt.figure(figsize=(12, 8))
num_cols = df.select_dtypes(include=['float64', 'int64']).columns
sns.heatmap(df[num_cols].corr(), annot=True, cmap='coolwarm', fmt=".2f")
plt.title('Correlation Matrix of Campaign Metrics')
plt.show()